//! Kong's Cargo environment for a project: the `cargo-home/config.toml` that
//! points crates-io at the vendored registry, the `cargo` wrapper that forces
//! that config with `--config`, the per-worktree workspace wrapper, the
//! activation scripts and the `export` lines of `kong env`.
//!
//! Everything lives under the gitignored `.rust-toolchain/` of the project:
//! nothing is committed and no `.cargo/config.toml` is ever written into it.

use std::path::{Path, PathBuf};

use anyhow::{Context, Result};
use tracing::{debug, info};

/// The four absolute paths every generated file is built from.
#[derive(Debug, Clone)]
pub struct CargoEnv {
    /// Project (worktree) root; `.rust-toolchain/` is created under it.
    pub project_root: PathBuf,
    /// The store toolchain's real cargo executable the wrapper execs.
    pub store_cargo: PathBuf,
    /// The vendored registry directory (`target_cache::vendor_dir`).
    pub vendor_dir: PathBuf,
    /// The shared target dir (`target_cache::target_dir`).
    pub target_dir: PathBuf,
}

impl CargoEnv {
    pub fn toolchain_dir(&self) -> PathBuf {
        self.project_root.join(".rust-toolchain")
    }
    pub fn cargo_home(&self) -> PathBuf {
        self.toolchain_dir().join("cargo-home")
    }
    pub fn config_path(&self) -> PathBuf {
        self.cargo_home().join("config.toml")
    }
    pub fn bin_dir(&self) -> PathBuf {
        self.toolchain_dir().join("bin")
    }
    /// Incremental artifacts of the project's own crates. They stay per
    /// worktree: Cargo hashes path packages relative to the workspace root, so
    /// two worktrees would otherwise share (and race on) one incremental session.
    pub fn incremental_dir(&self) -> PathBuf {
        self.toolchain_dir().join("incremental")
    }
    pub fn workspace_wrapper(&self) -> PathBuf {
        self.toolchain_dir().join("rustc-workspace-wrapper")
    }

    /// The environment variables of Kong's Cargo environment, in a fixed order.
    ///
    /// `RUSTC_WORKSPACE_WRAPPER` only applies to workspace members, so the
    /// dependency builds in the shared target dir keep the same fingerprint in
    /// every worktree. It is Unix-only: a `.cmd` cannot rewrite `key=value`
    /// arguments reliably (cmd splits them on `=`).
    pub fn vars(&self) -> Vec<(&'static str, String)> {
        let mut vars = vec![
            ("CARGO_HOME", display(&self.cargo_home())),
            ("CARGO_NET_OFFLINE", "true".to_string()),
            ("CARGO_TARGET_DIR", display(&self.target_dir)),
        ];
        if cfg!(unix) {
            vars.push(("RUSTC_WORKSPACE_WRAPPER", display(&self.workspace_wrapper())));
        }
        vars
    }
}

fn display(p: &Path) -> String {
    p.display().to_string()
}

/// A TOML basic or literal string with every special character escaped.
fn toml_str(s: &str) -> String {
    toml::Value::String(s.to_string()).to_string()
}

/// POSIX sh single-quoted word.
fn sh_quote(s: &str) -> String {
    format!("'{}'", s.replace('\'', r"'\''"))
}

/// PowerShell single-quoted string.
fn ps_quote(s: &str) -> String {
    format!("'{}'", s.replace('\'', "''"))
}

/// A double-quoted word in a `.cmd` file (`%` must be doubled there).
fn cmd_quote(s: &str) -> String {
    format!("\"{}\"", s.replace('%', "%%"))
}

/// `.rust-toolchain/cargo-home/config.toml`.
pub fn config_toml(env: &CargoEnv) -> String {
    format!(
        "# Generated by kong: crates come from the vendored store registry, offline.\n\
         [source.crates-io]\n\
         replace-with = \"kong-vendor\"\n\
         \n\
         [source.kong-vendor]\n\
         directory = {}\n\
         \n\
         [net]\n\
         offline = true\n\
         \n\
         [build]\n\
         target-dir = {}\n",
        toml_str(&display(&env.vendor_dir)),
        toml_str(&display(&env.target_dir)),
    )
}

/// `.rust-toolchain/bin/cargo`.
///
/// `--config <file>` is mandatory: a command-line config outranks every config
/// file, so a read-only `~/.cargo/config.toml` that replaces crates-io (loaded
/// as `CARGO_HOME` or as a parent-directory config) cannot win over it.
pub fn cargo_wrapper_sh(env: &CargoEnv) -> String {
    let mut s = String::from("#!/bin/sh\n# Generated by kong: the store cargo with kong's Cargo environment.\n");
    for (k, v) in env.vars() {
        s.push_str(&format!("export {k}={}\n", sh_quote(&v)));
    }
    s.push_str(&format!(
        "exec {} --config {} \"$@\"\n",
        sh_quote(&display(&env.store_cargo)),
        sh_quote(&display(&env.config_path()))
    ));
    s
}

/// `.rust-toolchain/bin/cargo.cmd` (Windows).
pub fn cargo_wrapper_cmd(env: &CargoEnv) -> String {
    let mut s = String::from("@echo off\r\nrem Generated by kong: the store cargo with kong's Cargo environment.\r\nsetlocal\r\n");
    for (k, v) in env.vars() {
        s.push_str(&format!("set \"{k}={}\"\r\n", v.replace('%', "%%")));
    }
    s.push_str(&format!(
        "{} --config {} %*\r\nexit /b %ERRORLEVEL%\r\n",
        cmd_quote(&display(&env.store_cargo)),
        cmd_quote(&display(&env.config_path()))
    ));
    s
}

/// `.rust-toolchain/rustc-workspace-wrapper`: runs `rustc "$@"` with the
/// incremental dir Cargo chose replaced by the per-worktree one. Release
/// builds pass no `incremental=` and go through unchanged.
pub fn workspace_wrapper_sh(env: &CargoEnv) -> String {
    let dir = sh_quote(&display(&env.incremental_dir()));
    format!(
        "#!/bin/sh\n\
         # Generated by kong: incremental artifacts of the project stay per worktree.\n\
         dir={dir}\n\
         first=1\n\
         for a do\n\
         \x20 if [ \"$first\" = 1 ]; then set --; first=0; fi\n\
         \x20 case \"$a\" in\n\
         \x20   incremental=*) a=\"incremental=$dir\" ;;\n\
         \x20   -Cincremental=*) a=\"-Cincremental=$dir\" ;;\n\
         \x20 esac\n\
         \x20 set -- \"$@\" \"$a\"\n\
         done\n\
         exec \"$@\"\n"
    )
}

/// `.rust-toolchain/activate.sh`. It is sourced, so it bakes absolute paths
/// in and never looks at `$0` (which names the caller's shell then).
pub fn activate_sh(env: &CargoEnv) -> String {
    let bin = display(&env.bin_dir());
    let mut s = String::from("# Generated by kong: source it (. .rust-toolchain/activate.sh).\n");
    for (k, v) in env.vars() {
        s.push_str(&format!("export {k}={}\n", sh_quote(&v)));
    }
    s.push_str(&format!(
        "case \":$PATH:\" in\n  *:{bin}:*) ;;\n  *) PATH={}:\"$PATH\" ;;\nesac\nexport PATH\n",
        sh_quote(&bin),
        bin = sh_quote(&bin)
    ));
    s
}

/// `.rust-toolchain/activate.ps1`.
pub fn activate_ps1(env: &CargoEnv) -> String {
    let mut s = String::from("# Generated by kong: dot-source it (. .rust-toolchain\\activate.ps1).\n");
    for (k, v) in env.vars() {
        s.push_str(&format!("$env:{k} = {}\n", ps_quote(&v)));
    }
    s.push_str(&format!(
        "$env:PATH = {} + [IO.Path]::PathSeparator + $env:PATH\n",
        ps_quote(&display(&env.bin_dir()))
    ));
    s
}

/// The same environment as `export K='V'` lines, for `eval "$(kong env)"`.
pub fn shell_exports(env: &CargoEnv) -> String {
    let mut s = String::new();
    for (k, v) in env.vars() {
        s.push_str(&format!("export {k}={}\n", sh_quote(&v)));
    }
    s.push_str(&format!(
        "export PATH={}\"$PATH\"\n",
        sh_quote(&format!("{}:", display(&env.bin_dir())))
    ));
    s
}

/// Write every file of the environment and create `cargo-home/` and the
/// incremental dir. Idempotent: a file is rewritten only when its content
/// differs. Returns how many files were (re)written.
///
/// `bin/cargo` is usually a hard link to the store cargo when this runs: it is
/// removed first, never written through, so the store binary stays intact.
/// The other toolchain binaries stay hard links.
pub fn write_all(env: &CargoEnv) -> Result<usize> {
    for dir in [env.cargo_home(), env.bin_dir(), env.incremental_dir()] {
        std::fs::create_dir_all(&dir)
            .with_context(|| format!("cannot create {}", dir.display()))?;
    }
    let mut files = vec![
        (env.config_path(), config_toml(env), false),
        (env.bin_dir().join("cargo"), cargo_wrapper_sh(env), true),
        (env.toolchain_dir().join("activate.sh"), activate_sh(env), false),
        (env.toolchain_dir().join("activate.ps1"), activate_ps1(env), false),
    ];
    if cfg!(unix) {
        files.push((env.workspace_wrapper(), workspace_wrapper_sh(env), true));
    }
    if cfg!(windows) {
        // cargo.exe would win over cargo.cmd in the PATHEXT lookup.
        remove_if_exists(&env.bin_dir().join("cargo.exe"))?;
        files.push((env.bin_dir().join("cargo.cmd"), cargo_wrapper_cmd(env), false));
    }
    let mut written = 0;
    for (path, content, executable) in &files {
        if write_if_changed(path, content, *executable)? {
            written += 1;
        }
    }
    info!(
        dir = %env.toolchain_dir().display(),
        written,
        "Cargo environment ready"
    );
    Ok(written)
}

fn remove_if_exists(path: &Path) -> Result<()> {
    match std::fs::remove_file(path) {
        Ok(()) => Ok(()),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(()),
        Err(e) => Err(e).with_context(|| format!("cannot remove {}", path.display())),
    }
}

fn write_if_changed(path: &Path, content: &str, executable: bool) -> Result<bool> {
    let same = match std::fs::metadata(path) {
        Ok(meta) if meta.len() == content.len() as u64 => {
            std::fs::read(path).map(|b| b == content.as_bytes()).unwrap_or(false)
        }
        _ => false,
    };
    if !same {
        // Unlink first: the old file may be a hard link into the store.
        remove_if_exists(path)?;
        std::fs::write(path, content).with_context(|| format!("cannot write {}", path.display()))?;
        debug!(path = %path.display(), "Wrote Cargo environment file");
    }
    #[cfg(unix)]
    if executable {
        use std::os::unix::fs::PermissionsExt;
        std::fs::set_permissions(path, std::fs::Permissions::from_mode(0o755))
            .with_context(|| format!("cannot make {} executable", path.display()))?;
    }
    #[cfg(not(unix))]
    let _ = executable;
    Ok(!same)
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::TempDir;

    fn env_in(tmp: &Path) -> CargoEnv {
        CargoEnv {
            project_root: tmp.join("proj"),
            store_cargo: tmp.join("store").join("cargo"),
            vendor_dir: tmp.join("cache").join("ven\"dor\\x"),
            target_dir: tmp.join("cache").join("target"),
        }
    }

    #[test]
    fn config_parses_with_expected_keys() {
        let tmp = TempDir::new().unwrap();
        let env = env_in(tmp.path());
        let v: toml::Value = toml::from_str(&config_toml(&env)).unwrap();
        assert_eq!(v["source"]["crates-io"]["replace-with"].as_str(), Some("kong-vendor"));
        assert_eq!(
            v["source"]["kong-vendor"]["directory"].as_str(),
            Some(display(&env.vendor_dir).as_str())
        );
        assert_eq!(v["net"]["offline"].as_bool(), Some(true));
        assert_eq!(
            v["build"]["target-dir"].as_str(),
            Some(display(&env.target_dir).as_str())
        );
    }

    #[test]
    fn wrapper_passes_config_before_user_args() {
        let tmp = TempDir::new().unwrap();
        let env = env_in(tmp.path());
        let sh = cargo_wrapper_sh(&env);
        let exec = sh.lines().find(|l| l.starts_with("exec ")).unwrap();
        let cfg = exec.find("--config").unwrap();
        assert!(exec[cfg..].contains(&display(&env.config_path())));
        assert!(exec.ends_with("\"$@\""));
        assert!(sh.contains("export CARGO_NET_OFFLINE='true'"));
        let cmd = cargo_wrapper_cmd(&env);
        assert!(cmd.find("--config").unwrap() < cmd.find("%*").unwrap());
    }

    #[test]
    fn exports_are_single_quoted() {
        let tmp = TempDir::new().unwrap();
        let mut env = env_in(tmp.path());
        env.target_dir = PathBuf::from("/c/it's");
        let out = shell_exports(&env);
        assert!(out.contains(r"export CARGO_TARGET_DIR='/c/it'\''s'"));
        assert!(out.lines().all(|l| l.starts_with("export ")));
        assert!(out.contains("export PATH='"));
    }

    #[test]
    fn write_is_idempotent_and_replaces_the_hard_link() {
        let tmp = TempDir::new().unwrap();
        let env = env_in(tmp.path());
        std::fs::create_dir_all(env.store_cargo.parent().unwrap()).unwrap();
        std::fs::write(&env.store_cargo, b"real cargo").unwrap();
        std::fs::create_dir_all(env.bin_dir()).unwrap();
        std::fs::hard_link(&env.store_cargo, env.bin_dir().join("cargo")).unwrap();

        assert!(write_all(&env).unwrap() >= 4);
        assert_eq!(std::fs::read(&env.store_cargo).unwrap(), b"real cargo");
        assert_eq!(
            std::fs::read_to_string(env.bin_dir().join("cargo")).unwrap(),
            cargo_wrapper_sh(&env)
        );
        assert_eq!(write_all(&env).unwrap(), 0);

        std::fs::write(env.config_path(), "stale").unwrap();
        assert_eq!(write_all(&env).unwrap(), 1);
        assert_eq!(std::fs::read_to_string(env.config_path()).unwrap(), config_toml(&env));
    }

    #[cfg(unix)]
    fn run_sh(script: &str) -> String {
        let out = std::process::Command::new("sh").arg("-c").arg(script).output().unwrap();
        assert!(out.status.success(), "{}", String::from_utf8_lossy(&out.stderr));
        String::from_utf8(out.stdout).unwrap()
    }

    #[cfg(unix)]
    #[test]
    fn wrappers_and_activate_run() {
        use std::os::unix::fs::PermissionsExt;
        let tmp = TempDir::new().unwrap();
        let env = env_in(tmp.path());
        std::fs::create_dir_all(env.store_cargo.parent().unwrap()).unwrap();
        std::fs::write(
            &env.store_cargo,
            "#!/bin/sh\necho \"$CARGO_HOME|$CARGO_NET_OFFLINE|$CARGO_TARGET_DIR\"\nprintf '%s\\n' \"$@\"\n",
        )
        .unwrap();
        std::fs::set_permissions(&env.store_cargo, std::fs::Permissions::from_mode(0o755)).unwrap();
        write_all(&env).unwrap();

        let wrapper = env.bin_dir().join("cargo");
        let out = run_sh(&format!("{} build 'a b'", sh_quote(&display(&wrapper))));
        let lines: Vec<&str> = out.lines().collect();
        assert_eq!(
            lines[0],
            format!("{}|true|{}", env.cargo_home().display(), env.target_dir.display())
        );
        assert_eq!(&lines[1..], &["--config", display(&env.config_path()).as_str(), "build", "a b"]);

        let ws = run_sh(&format!(
            "{} printf '%s\\n' -C incremental=/shared/inc --crate-name x",
            sh_quote(&display(&env.workspace_wrapper()))
        ));
        let inc = format!("incremental={}", env.incremental_dir().display());
        assert_eq!(ws.lines().collect::<Vec<_>>(), vec!["-C", inc.as_str(), "--crate-name", "x"]);

        let act = run_sh(&format!(
            "PATH=/usr/bin:/bin; . {p}; . {p}; echo \"$CARGO_HOME\"; echo \"$PATH\"",
            p = sh_quote(&display(&env.toolchain_dir().join("activate.sh")))
        ));
        let lines: Vec<&str> = act.lines().collect();
        assert_eq!(lines[0], display(&env.cargo_home()));
        assert_eq!(lines[1], format!("{}:/usr/bin:/bin", env.bin_dir().display()));
    }
}
